export const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
export const finite=v=>v!==null&&v!==''&&v!==undefined&&Number.isFinite(Number(v));
export function regressionMetrics(y,p){const ok=y.map((v,i)=>[v,p[i]]).filter(([v,w])=>finite(v)&&finite(w));if(!ok.length)return{mae:null,rmse:null,r2:null,mape:null,n:0};const n=ok.length,mean=ok.reduce((s,[v])=>s+v,0)/n,ss=ok.reduce((s,[v])=>s+(v-mean)**2,0),se=ok.reduce((s,[v,w])=>s+(v-w)**2,0),nz=ok.filter(([v])=>Math.abs(v)>1e-8);return{mae:ok.reduce((s,[v,w])=>s+Math.abs(v-w),0)/n,rmse:Math.sqrt(se/n),r2:ss>1e-12?1-se/ss:null,mape:nz.length?nz.reduce((s,[v,w])=>s+Math.abs((v-w)/v),0)/nz.length*100:null,n};}
export function arpsRate(t,qi,di,b){if(![t,qi,di,b].every(Number.isFinite)||t<0||qi<0||di<0||b<0)return NaN;return b<1e-7?qi*Math.exp(-di*t):qi/Math.pow(1+b*di*t,1/b);}
export function fitArps(points,{horizon=180}={}){const rows=points.filter(p=>finite(p.t)&&finite(p.q)&&p.q>0).map(p=>({t:Number(p.t),q:Number(p.q)})).sort((a,b)=>a.t-b.t);if(rows.length<20)throw Error('至少需要20个有效正产量观测');const origin=rows[0].t;rows.forEach(r=>r.t-=origin);const n=rows.length,nt=Math.floor(n*.7),nv=Math.floor(n*.15),tr=rows.slice(0,nt),va=rows.slice(nt,nt+nv),te=rows.slice(nt+nv),candidates=[];
for(let bi=0;bi<=15;bi++){const b=bi/10;for(let k=0;k<90;k++){const di=Math.exp(Math.log(.00001)+k/89*Math.log(20000));const g=tr.map(p=>arpsRate(p.t,1,di,b));const qi=tr.reduce((s,p,i)=>s+p.q*g[i],0)/g.reduce((s,v)=>s+v*v,0);const loss=tr.reduce((s,p)=>s+(p.q-arpsRate(p.t,qi,di,b))**2,0)/tr.length;candidates.push({qi,di,b,loss});}}
const shortlist=candidates.sort((a,b)=>a.loss-b.loss).slice(0,30);for(const c of shortlist)c.val=va.reduce((s,p)=>s+(p.q-arpsRate(p.t,c.qi,c.di,c.b))**2,0)/va.length;const best=shortlist.sort((a,b)=>a.val-b.val)[0];const metrics={};for(const [name,list]of Object.entries({train:tr,validation:va,test:te}))metrics[name]=regressionMetrics(list.map(p=>p.q),list.map(p=>arpsRate(p.t,best.qi,best.di,best.b)));return{parameters:{qi:best.qi,di:best.di,b:best.b},metrics,splits:{train:nt,validation:nv,test:te.length},ratios:[nt/n,nv/n,te.length/n],fit:rows.map((p,i)=>({...p,prediction:arpsRate(p.t,best.qi,best.di,best.b),split:i<nt?'train':i<nt+nv?'validation':'test'})),forecast:Array.from({length:Math.ceil(horizon/7)+1},(_,i)=>({t:rows.at(-1).t+i*7,q:arpsRate(rows.at(-1).t+i*7,best.qi,best.di,best.b)})),policy:'按时间70/15/15；参数仅训练拟合、验证选择，测试不参与选择'};}
export function checkQuality(rows){let missingCells=0;const blocking=[],warnings=[],duplicates=[],seen=new Set();for(let i=0;i<rows.length;i++){const r=rows[i],key=r.sample_id??`${r.well_id??r.well_name??''}:${r.date??r.DEPTH_MD??i}`;if(seen.has(key))duplicates.push(i);seen.add(key);for(const [k,v]of Object.entries(r))if(v===null||v===undefined||v==='')missingCells++;const reasons=[];for(const k of ['oil_volume_sm3','water_volume_sm3','water_injection_volume_sm3'])if(finite(r[k])&&Number(r[k])<0)reasons.push(k+'不能为负');if(finite(r.water_cut)&&(r.water_cut<0||r.water_cut>1))reasons.push('含水比例越界');if(finite(r.on_stream_hours)&&(r.on_stream_hours<0||r.on_stream_hours>24.01))reasons.push('开井时长越界');if(finite(r.RHOB)&&(r.RHOB<.5||r.RHOB>5))reasons.push('密度超出配置范围');if(finite(r.oil_volume_sm3)&&finite(r.water_volume_sm3)&&finite(r.water_cut)&&r.oil_volume_sm3+r.water_volume_sm3>0&&Math.abs(r.water_cut-r.water_volume_sm3/(r.oil_volume_sm3+r.water_volume_sm3))>.001)reasons.push('油水体积与含水比例不一致');if(finite(r.log_depth_m)&&finite(r.core_depth_m)&&Math.abs(r.log_depth_m-r.core_depth_m)>2)reasons.push('跨专业深度差异>2m');if(finite(r.phi_log)&&finite(r.phi_core)&&Math.abs(r.phi_log-r.phi_core)>.04)warnings.push({index:i,key,reason:'测井与岩心孔隙度差异>0.04'});if(reasons.length)blocking.push({index:i,key,reasons});if(finite(r.AVG_DOWNHOLE_PRESSURE)&&r.AVG_DOWNHOLE_PRESSURE===0)warnings.push({index:i,key,reason:'零压力保留原值，需核查'});}
const fields=rows.length?Object.keys(rows[0]).length:0;return{rows:rows.length,missingCells,blocking,warnings,duplicates,completeness:fields&&rows.length?1-missingCells/(fields*rows.length):null,records:rows.map(r=>({...r})),level:blocking.length||duplicates.length?'L0':warnings.length||missingCells?'L1':'L3'};}
export function historicalMatches(query,events,{limit=5,days=30}={}){const day=864e5,qtime=Date.parse(query.date);return events.filter(e=>e.well_id===query.well_id&&Date.parse(e.date)<qtime-days*day&&e.split!=='test').map(e=>{const a=new Set(query.patterns??[]),b=new Set(e.patterns??[]),intersection=[...a].filter(v=>b.has(v)).length,union=new Set([...a,...b]).size;const temporal=['oil_relative_change','water_cut_delta','pressure_relative_change'].reduce((s,k)=>s+(finite(e[k])&&finite(query[k])?Math.abs(e[k]-query[k]):0),0);return{...e,similarity:union?intersection/union:0,distance:temporal};}).sort((a,b)=>b.similarity-a.similarity||a.distance-b.distance).filter((e,i,all)=>all.slice(0,i).every(o=>Math.abs(Date.parse(o.date)-Date.parse(e.date))>20*day)).slice(0,limit);}
export function queryGraph(graph,query,{source=null,limit=70}={}){const q=String(query??'').trim().toLowerCase(),eligible=graph.nodes.filter(n=>!source||n.source===source);if(!q)return{nodes:eligible.slice(0,limit),edges:graph.edges.filter(e=>eligible.slice(0,limit).some(n=>n.id===e.source_id)&&eligible.slice(0,limit).some(n=>n.id===e.target_id))};const found=eligible.filter(n=>[n.id,n.label].some(x=>String(x).toLowerCase().includes(q)));if(!found.length)return{nodes:[],edges:[]};const ids=new Set(found.map(n=>n.id)),direct=graph.edges.filter(e=>ids.has(e.source_id)||ids.has(e.target_id));for(const e of direct){ids.add(e.source_id);ids.add(e.target_id);}const nodes=graph.nodes.filter(n=>ids.has(n.id)).slice(0,limit),selected=new Set(nodes.map(n=>n.id));return{nodes,edges:direct.filter(e=>selected.has(e.source_id)&&selected.has(e.target_id))};}
export function dagOrder(nodes){const byId=new Map(nodes.map(n=>[n.id,n])),ordered=[],visiting=new Set(),done=new Set();function visit(id){if(visiting.has(id))throw Error('DAG cycle detected');if(done.has(id))return;const n=byId.get(id);if(!n)throw Error('Missing DAG dependency '+id);visiting.add(id);for(const d of n.deps??[])visit(d);visiting.delete(id);done.add(id);ordered.push(id);}for(const n of nodes)visit(n.id);return ordered;}
export function canRunNode(node,status){return(node.deps??[]).every(d=>status[d]==='completed');}
export function aggregateProduction(rows){const sum=k=>{const v=rows.map(r=>r[k]).filter(finite);return v.length?v.reduce((a,b)=>a+Number(b),0):null;},oil=sum('oil_volume_sm3'),water=sum('water_volume_sm3'),injection=sum('water_injection_volume_sm3');return{oil,water,injection,liquid:oil!==null&&water!==null?oil+water:null,waterCut:oil+water>0?water/(oil+water):null,surfaceInjectionRatio:oil+water>0&&injection!==null?injection/(oil+water):null};}
export function alignEntity(text,entities){const norm=s=>String(s).normalize('NFKC').toLowerCase().replace(/\s|井号|井|油田|field/g,'').replace(/_/g,'/');const q=norm(text);const exact=entities.filter(e=>norm(e.label)===q||norm(e.id)===q);if(exact.length)return exact.map(e=>({...e,method:'标准编码/别名精确匹配',score:1}));return entities.map(e=>{const a=new Set(norm(e.label)),b=new Set(q),u=new Set([...a,...b]);return{...e,method:'字符集合相似度候选，需复核',score:[...a].filter(x=>b.has(x)).length/(u.size||1)}}).filter(e=>e.score>.25).sort((a,b)=>b.score-a.score).slice(0,5);}
export function searchDocuments(query,corpus,limit=5){const aliases={'日产油':'产油','出水':'产水','含水':'产水','油量':'产油','水量':'产水'};let q=String(query).toLowerCase();for(const[a,b]of Object.entries(aliases))q=q.replaceAll(a,b);const tokens=s=>{const t=s.toLowerCase().match(/[a-z0-9]+(?:[\/-][a-z0-9]+)*|[\u4e00-\u9fff]/g)??[];return [...t,...t.slice(1).map((v,i)=>t[i]+v)]};const qt=tokens(q),qset=new Set(qt);return corpus.map(d=>{const dt=tokens(d.text),set=new Set(dt);let score=0;for(const t of qset)if(set.has(t))score+=/\d/.test(t)?4:t.length>1?2:1;return{...d,score:score/Math.sqrt(Math.max(1,dt.length))};}).filter(d=>d.score>0).sort((a,b)=>b.score-a.score).slice(0,limit);}
export function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),delimiter=lines[0]?.includes(';')?';':',';const parse=l=>{const out=[];let val='',quote=false;for(let i=0;i<l.length;i++){if(l[i]==='"'){if(quote&&l[i+1]==='"'){val+='"';i++;}else quote=!quote;}else if(l[i]===delimiter&&!quote){out.push(val);val='';}else val+=l[i];}out.push(val);return out};const headers=parse(lines.shift()??'');if(!headers.length)throw Error('CSV缺少表头');return lines.map(line=>Object.fromEntries(parse(line).map((v,i)=>[headers[i],v===''?null:Number.isFinite(Number(v))?Number(v):v])));}
export function aggregatePeriod(rows,period='day'){const groups=new Map();for(const row of rows){const key=period==='month'?row.date.slice(0,7)+'-01':row.date;const g=groups.get(key)??[];g.push(row);groups.set(key,g)}return[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([date,g])=>{const t=aggregateProduction(g),press=g.map(x=>x.pressure_for_model_source_unit).filter(finite);return{date,oil_volume_sm3:t.oil,water_volume_sm3:t.water,water_injection_volume_sm3:t.injection,liquid_volume_sm3:t.liquid,water_cut:t.waterCut,pressure_for_model_source_unit:press.length?press.reduce((a,b)=>a+b,0)/press.length:null,record_count:g.length,aggregation:period}})}
export function lagCorrelation(injection,production,{maxLag=90,minPoints=20}={}){const im=new Map(injection.filter(x=>finite(x.value)).map(x=>[x.date,Number(x.value)])),pm=new Map(production.filter(x=>finite(x.value)).map(x=>[x.date,Number(x.value)])),rows=[];for(let lag=0;lag<=maxLag;lag++){const pairs=[];for(const[d,q]of pm){const source=new Date(Date.parse(d)-lag*864e5).toISOString().slice(0,10);if(im.has(source))pairs.push([im.get(source),q]);}if(pairs.length<minPoints){rows.push({lag,correlation:null,pairs:pairs.length});continue}const mx=pairs.reduce((s,p)=>s+p[0],0)/pairs.length,my=pairs.reduce((s,p)=>s+p[1],0)/pairs.length;let cov=0,vx=0,vy=0;for(const[x,y]of pairs){cov+=(x-mx)*(y-my);vx+=(x-mx)**2;vy+=(y-my)**2;}rows.push({lag,correlation:vx&&vy?cov/Math.sqrt(vx*vy):null,pairs:pairs.length});}const valid=rows.filter(r=>r.correlation!==null),best=valid.sort((a,b)=>Math.abs(b.correlation)-Math.abs(a.correlation))[0]??null;return{rows,best,method:'calendar-aligned Pearson lag correlation; no causal or hydraulic interpretation'};}
export function grinView(ex,wellId,feature=0,{maxGap=3}={}){const j=ex.well_ids.indexOf(wellId);if(j<0)throw Error('GRIN冻结窗口没有该井');const input=[],prediction=[],target=[],rows=[];let heldout=0,rejected=0;for(let t=0;t<ex.dates.length;t++){const masked=Boolean(ex.holdout_mask[t][j][feature]),raw=ex.prediction[t][j][feature],v=ex.input[t][j][feature];let gap=0;if(masked){gap=1;for(let b=t-1;b>=0&&ex.holdout_mask[b][j][feature];b--)gap++;for(let b=t+1;b<ex.dates.length&&ex.holdout_mask[b][j][feature];b++)gap++;}const valid=masked&&raw>=0&&gap<=maxGap;input.push(v);prediction.push(masked?raw:null);target.push(masked?ex.target_observed[t][j][feature]:null);if(masked)heldout++;if(masked&&!valid)rejected++;rows.push({date:ex.dates[t],well_id:wellId,feature:ex.feature_names[feature],input_value:v,prediction:masked?raw:null,target:masked?ex.target_observed[t][j][feature]:null,holdout:masked,output_value:valid?raw:v,status:masked?(valid?'重建候选':'物理约束未通过／长缺口待核查'):v===null?'自然缺失保留':'原观测保留'})}return{input,prediction,target,rows,heldout,rejected,window_id:ex.window_id,well_id:wellId,feature:ex.feature_names[feature]};}
export function switchWellState(state,well){return{...state,well,qualityResult:null,qualityRun:false,arpsResult:null,eventIndex:0,objectScope:'well'};}
export function newWorkflowState(state,runId,token){return{...state,workflowRunId:runId,workflowToken:token,workflowOutput:null,workflowStatus:{},workflowLogs:[],workflowRunning:true,workflowPaused:false};}
export function isActiveRun(state,token){return state.workflowToken===token&&state.workflowRunning===true;}
export function normalizeField(values,nx,ny){const flat=Array.from(values??[]).flat(Infinity).map(Number);if(flat.length!==nx*ny||flat.some(v=>!Number.isFinite(v)))throw Error('Scientific field shape or finite-value mismatch');return flat;}
